local SCRIPT_VER    = "v1 beta"

-- ══════════════════════════════════════════════════
--  SERVICES / UTILS
-- ══════════════════════════════════════════════════
local Players      = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local lp           = Players.LocalPlayer
local function getGui()
    local ok, g = pcall(function() return game:GetService("CoreGui") end)
    return ok and g or lp:WaitForChild("PlayerGui")
end
local function tw(obj, t, props, style, dir)
    style = style or Enum.EasingStyle.Quad
    dir   = dir   or Enum.EasingDirection.Out
    local tween = TweenService:Create(obj, TweenInfo.new(t, style, dir), props)
    tween:Play()
    return tween
end
local function lerp(a, b, t) return a + (b - a) * t end

-- ══════════════════════════════════════════════════
--  KEY PERSISTENCE
-- ══════════════════════════════════════════════════
local function readKey()
    if readfile then
        local ok, v = pcall(readfile, KEY_FILE)
        if ok and type(v) == "string" then return v:match("^%s*(.-)%s*$") end
    end
    return nil
end
local function saveKey(k)
    if writefile then pcall(writefile, KEY_FILE, k) end
end

