    keyFrame.Position = UDim2.new(0.5,-210,0.5,80)
    keyFrame.BackgroundColor3 = Color3.fromRGB(14,16,22)
    keyFrame.BorderSizePixel = 0
    keyFrame.BackgroundTransparency = 1
    local kfCorner = Instance.new("UICorner", keyFrame)
    kfCorner.CornerRadius = UDim.new(0,10)
    local kfStroke = Instance.new("UIStroke", keyFrame)
    kfStroke.Color = Color3.fromRGB(40,45,65)
    kfStroke.Thickness = 1
    kfStroke.Transparency = 1

    local keyTitle = Instance.new("TextLabel", keyFrame)
    keyTitle.Size = UDim2.new(1,-24,0,28)
    keyTitle.Position = UDim2.new(0,12,0,12)
    keyTitle.BackgroundTransparency = 1
    keyTitle.Text = "Enter your key"
    keyTitle.Font = Enum.Font.GothamBold
    keyTitle.TextSize = 15
    keyTitle.TextColor3 = Color3.fromRGB(220,225,245)
    keyTitle.TextXAlignment = Enum.TextXAlignment.Left
    keyTitle.TextTransparency = 1

    local keyDiscord = Instance.new("TextLabel", keyFrame)
    keyDiscord.Size = UDim2.new(1,-24,0,18)
    keyDiscord.Position = UDim2.new(0,12,0,38)
    keyDiscord.BackgroundTransparency = 1
    keyDiscord.Text = "Keys available at " .. DISCORD_LINK
    keyDiscord.Font = Enum.Font.Gotham
    keyDiscord.TextSize = 12
    keyDiscord.TextColor3 = Color3.fromRGB(96,165,250)
    keyDiscord.TextXAlignment = Enum.TextXAlignment.Left
    keyDiscord.TextTransparency = 1

    local keyBox = Instance.new("TextBox", keyFrame)
    keyBox.Size = UDim2.new(1,-24,0,38)
    keyBox.Position = UDim2.new(0,12,0,66)
    keyBox.BackgroundColor3 = Color3.fromRGB(20,23,32)
    keyBox.BorderSizePixel = 0
    keyBox.Text = ""
    keyBox.PlaceholderText = "SURF-XXXX-XXXX"
    keyBox.Font = Enum.Font.Code
    keyBox.TextSize = 15
    keyBox.TextColor3 = Color3.fromRGB(220,225,245)
    keyBox.PlaceholderColor3 = Color3.fromRGB(70,80,110)
    keyBox.BackgroundTransparency = 1
    local kbCorner = Instance.new("UICorner", keyBox)
    kbCorner.CornerRadius = UDim.new(0,8)
    local kbStroke = Instance.new("UIStroke", keyBox)
    kbStroke.Color = Color3.fromRGB(50,60,90)
    kbStroke.Thickness = 1
    kbStroke.Transparency = 1

    local keyBtn = Instance.new("TextButton", keyFrame)
    keyBtn.Size = UDim2.new(1,-24,0,36)
    keyBtn.Position = UDim2.new(0,12,0,118)
    keyBtn.BackgroundColor3 = Color3.fromRGB(96,165,250)
    keyBtn.BorderSizePixel = 0
    keyBtn.Text = "Unlock"
    keyBtn.Font = Enum.Font.GothamBold
    keyBtn.TextSize = 14
    keyBtn.TextColor3 = Color3.fromRGB(255,255,255)
    keyBtn.BackgroundTransparency = 1
    local kbtnCorner = Instance.new("UICorner", keyBtn)
    kbtnCorner.CornerRadius = UDim.new(0,8)
    local kbtnGrad = Instance.new("UIGradient", keyBtn)
    kbtnGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(96,165,250)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(139,92,246)),
    })
    kbtnGrad.Rotation = 90

    local keyError = Instance.new("TextLabel", keyFrame)
    keyError.Size = UDim2.new(1,-24,0,16)
    keyError.Position = UDim2.new(0,12,1,-4)
    keyError.BackgroundTransparency = 1
    keyError.Text = ""
    keyError.Font = Enum.Font.Gotham
    keyError.TextSize = 12
    keyError.TextColor3 = Color3.fromRGB(255,80,80)
    keyError.TextXAlignment = Enum.TextXAlignment.Left
    keyError.TextTransparency = 1

    -- ── PHASE 1: FADE IN ───────────────────────────
    local function phase1()
        tw(overlay, 0.5, {BackgroundTransparency = 0})
        task.wait(0.3)
        tw(glow, 0.8, {BackgroundTransparency = 0.92}, Enum.EasingStyle.Sine)
        task.wait(0.15)
        tw(iconBox, 0.5, {BackgroundTransparency = 0})
        tw(iconLabel, 0.5, {TextTransparency = 0})
        task.wait(0.1)
        tw(titleLabel, 0.6, {TextTransparency = 0}, Enum.EasingStyle.Expo)
        tw(verLabel, 0.6, {TextTransparency = 0})
        task.wait(0.4)
        tw(accentLine, 0.6, {Size = UDim2.new(0,420,0,2)}, Enum.EasingStyle.Expo)
        task.wait(0.3)
        tw(statusLabel, 0.4, {TextTransparency = 0})
        tw(barTrack, 0.4, {BackgroundTransparency = 0})
    end

    -- ── PHASE 2: PROGRESS BAR ─────────────────────
    local steps = {
        {frac=0.20, text="initializing runtime..."},
        {frac=0.45, text="loading modules..."},
        {frac=0.70, text="applying hooks..."},
        {frac=0.90, text="checking key..."},
    }
    local function runProgress(onDone)
        for _, step in ipairs(steps) do
            statusLabel.Text = step.text
            tw(barFill, 0.55, {Size = UDim2.new(step.frac,0,1,0)}, Enum.EasingStyle.Expo)
            -- shimmer sweep
            task.spawn(function()
                tw(shimmer, 0.55, {Position = UDim2.new(1,0,0,0)}, Enum.EasingStyle.Quad)
                task.wait(0.56)
                shimmer.Position = UDim2.new(0,-60,0,0)
            end)
            task.wait(0.6)
        end
        onDone()
    end

    -- ── PHASE 3: KEY GATE ─────────────────────────
    local function showKeyGate(onValid)
        tw(keyFrame, 0.4, {BackgroundTransparency = 0})
        tw(kfStroke, 0.4, {Transparency = 0})
        tw(keyTitle, 0.4, {TextTransparency = 0})
        tw(keyDiscord, 0.4, {TextTransparency = 0})
        tw(keyBox, 0.4, {BackgroundTransparency = 0})
        tw(kbStroke, 0.4, {Transparency = 0})
        tw(keyBtn, 0.4, {BackgroundTransparency = 0})
        tw(keyError, 0.4, {TextTransparency = 0})
        statusLabel.Text = "waiting for key..."

        local function tryKey()
            local input = keyBox.Text:match("^%s*(.-)%s*$"):upper()
            if VALID_KEYS[input] then
                saveKey(input)
                tw(keyError, 0.2, {TextTransparency = 1})
                tw(keyBtn, 0.3, {BackgroundColor3 = Color3.fromRGB(50,200,100)})
                keyBtn.Text = "✓ Unlocked"
                task.wait(0.5)
                -- hide key frame
                tw(keyFrame, 0.35, {BackgroundTransparency = 1})
                tw(kfStroke, 0.35, {Transparency = 1})
                tw(keyTitle, 0.25, {TextTransparency = 1})
                tw(keyDiscord, 0.25, {TextTransparency = 1})
                tw(keyBox, 0.25, {BackgroundTransparency = 1})
                tw(kbStroke, 0.25, {Transparency = 1})
                tw(keyBtn, 0.25, {BackgroundTransparency = 1})
                task.wait(0.4)
                onValid()
            else
                keyError.Text = "invalid key — try again"
                tw(keyBox, 0.08, {BackgroundColor3 = Color3.fromRGB(60,20,20)})
                task.wait(0.08)
                tw(keyBox, 0.15, {BackgroundColor3 = Color3.fromRGB(20,23,32)})
            end
        end

        keyBtn.MouseButton1Click:Connect(tryKey)
        keyBox.FocusLost:Connect(function(ep) if ep then tryKey() end end)
    end

    -- ── PHASE 4: LAUNCH ───────────────────────────
    local function launch()
        statusLabel.Text = "launching surface..."
        tw(barFill, 0.4, {Size = UDim2.new(1,0,1,0)}, Enum.EasingStyle.Expo)
        barGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(50,200,100)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(80,230,140)),
        })
        task.wait(0.5)
        statusLabel.Text = "ready."
        task.wait(0.4)
        -- fade everything out
        tw(overlay, 0.6, {BackgroundTransparency = 1}, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
        tw(glow, 0.4, {BackgroundTransparency = 1})
        task.wait(0.65)
        sg:Destroy()
        onReady()
    end

    -- ── BOOT SEQUENCE ─────────────────────────────
    task.spawn(function()
        phase1()

        -- check saved key first
        local saved = readKey()
        if saved and VALID_KEYS[saved] then
            -- skip key gate, run progress then launch
            runProgress(function()
                launch()
            end)
        else
            -- run progress up to 90% then show key gate
            runProgress(function()
                showKeyGate(function()
                    launch()
                end)
            end)
        end
    end)
end

-- ══════════════════════════════════════════════════
--  EXECUTE
-- ══════════════════════════════════════════════════
runBoot(function()
    local fn, er = loadstring(_pl)
    if fn then fn()
    else warn("[Surface] exec failed: "..tostring(er)) end
end)
